// Embedded sfnt TrueType font subsets (UI Regular, UI Bold, and Monospace).
// Parses TrueType cmap, hmtx, loca, and glyf tables directly with zero external runtime dependencies.

export interface GlyphPoint {
  readonly x: number;
  readonly y: number;
  readonly onCurve: boolean;
}

export interface GlyphOutline {
  readonly codePoint: number;
  readonly advanceWidth: number;
  readonly leftSideBearing: number;
  readonly xMin: number;
  readonly yMin: number;
  readonly xMax: number;
  readonly yMax: number;
  readonly contours: readonly (readonly GlyphPoint[])[];
}

export interface EmbeddedFont {
  readonly unitsPerEm: number;
  readonly ascender: number;
  readonly descender: number;
  readonly numGlyphs: number;
  readonly cmap: ReadonlyMap<number, number>;
}

const EMBEDDED_UI_REGULAR_SFNT_BASE64 = "";
const EMBEDDED_UI_BOLD_SFNT_BASE64 = "";
const EMBEDDED_MONO_SFNT_BASE64 = "";

type FontVariant = "ui-regular" | "ui-bold" | "mono";

interface RawGlyphData {
  readonly advanceWidth: number;
  readonly lsb: number;
  readonly xMin: number;
  readonly yMin: number;
  readonly xMax: number;
  readonly yMax: number;
  readonly contours: readonly (readonly GlyphPoint[])[];
}

interface ParsedSfnt extends EmbeddedFont {
  readonly rawGlyphs: readonly RawGlyphData[];
}

const cachedFonts = new Map<FontVariant, ParsedSfnt>();
const outlineCache = new Map<string, GlyphOutline>();

function decodeBase64(encoded: string): Uint8Array {
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function parseSfnt(variant: FontVariant = "ui-regular"): ParsedSfnt {
  const existingFont = cachedFonts.get(variant);
  if (existingFont) return existingFont;

  const b64 =
    variant === "ui-bold"
      ? EMBEDDED_UI_BOLD_SFNT_BASE64
      : variant === "mono"
        ? EMBEDDED_MONO_SFNT_BASE64
        : EMBEDDED_UI_REGULAR_SFNT_BASE64;

  const bytes = decodeBase64(b64);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const numTables = view.getUint16(4);
  const tables: Record<string, { offset: number; length: number }> = {};
  for (let i = 0; i < numTables; i++) {
    const rec = 12 + i * 16;
    const tag = String.fromCharCode(
      bytes[rec]!,
      bytes[rec + 1]!,
      bytes[rec + 2]!,
      bytes[rec + 3]!
    );
    tables[tag] = {
      offset: view.getUint32(rec + 8),
      length: view.getUint32(rec + 12)
    };
  }

  const headOff = tables.head!.offset;
  const hheaOff = tables.hhea!.offset;
  const maxpOff = tables.maxp!.offset;
  const hmtxOff = tables.hmtx!.offset;
  const locaOff = tables.loca!.offset;
  const glyfOff = tables.glyf!.offset;
  const cmapOff = tables.cmap!.offset;

  const unitsPerEm = view.getUint16(headOff + 18);
  const ascender = view.getInt16(hheaOff + 4);
  const descender = view.getInt16(hheaOff + 6);
  const numHMetrics = view.getUint16(hheaOff + 34);
  const numGlyphs = view.getUint16(maxpOff + 4);

  const cmap = new Map<number, number>();
  const cmapSubCount = view.getUint16(cmapOff + 2);
  for (let i = 0; i < cmapSubCount; i++) {
    const sub = cmapOff + view.getUint32(cmapOff + 8 + i * 8);
    const format = view.getUint16(sub);
    if (format === 12) {
      const nGroups = view.getUint32(sub + 12);
      for (let g = 0; g < nGroups; g++) {
        const gOff = sub + 16 + g * 12;
        const startCode = view.getUint32(gOff);
        const endCode = view.getUint32(gOff + 4);
        const startGid = view.getUint32(gOff + 8);
        for (let cp = startCode; cp <= endCode; cp++) {
          cmap.set(cp, startGid + (cp - startCode));
        }
      }
    }
  }

  const resolvedGlyphs: (RawGlyphData | undefined)[] = new Array(numGlyphs);

  function decodeGlyph(gid: number): RawGlyphData {
    const existing = resolvedGlyphs[gid];
    if (existing) return existing;

    const adv =
      gid < numHMetrics
        ? view.getUint16(hmtxOff + gid * 4)
        : view.getUint16(hmtxOff + (numHMetrics - 1) * 4);
    const lsb =
      gid < numHMetrics
        ? view.getInt16(hmtxOff + gid * 4 + 2)
        : view.getInt16(hmtxOff + numHMetrics * 4 + (gid - numHMetrics) * 2);

    const gStart = view.getUint32(locaOff + gid * 4);
    const gEnd = view.getUint32(locaOff + (gid + 1) * 4);
    if (gStart === gEnd) {
      const empty: RawGlyphData = {
        advanceWidth: adv,
        lsb,
        xMin: 0,
        yMin: 0,
        xMax: 0,
        yMax: 0,
        contours: []
      };
      resolvedGlyphs[gid] = empty;
      return empty;
    }

    const pos = glyfOff + gStart;
    const numContours = view.getInt16(pos);
    const xMin = view.getInt16(pos + 2);
    const yMin = view.getInt16(pos + 4);
    const xMax = view.getInt16(pos + 6);
    const yMax = view.getInt16(pos + 8);

    if (numContours >= 0) {
      const endPts: number[] = [];
      for (let c = 0; c < numContours; c++) {
        endPts.push(view.getUint16(pos + 10 + c * 2));
      }
      const totalPts = numContours > 0 ? endPts[numContours - 1]! + 1 : 0;
      const insnLen = view.getUint16(pos + 10 + numContours * 2);
      let cursor = pos + 12 + numContours * 2 + insnLen;

      const flags: number[] = [];
      while (flags.length < totalPts) {
        const flag = bytes[cursor++]!;
        flags.push(flag);
        if ((flag & 8) !== 0) {
          const repeatCount = bytes[cursor++]!;
          for (let r = 0; r < repeatCount; r++) {
            flags.push(flag);
          }
        }
      }

      const xs: number[] = new Array(totalPts);
      let x = 0;
      for (let i = 0; i < totalPts; i++) {
        const flag = flags[i]!;
        if ((flag & 2) !== 0) {
          const dx = bytes[cursor++]!;
          x += (flag & 16) !== 0 ? dx : -dx;
        } else if ((flag & 16) === 0) {
          x += view.getInt16(cursor);
          cursor += 2;
        }
        xs[i] = x;
      }

      const ys: number[] = new Array(totalPts);
      let y = 0;
      for (let i = 0; i < totalPts; i++) {
        const flag = flags[i]!;
        if ((flag & 4) !== 0) {
          const dy = bytes[cursor++]!;
          y += (flag & 32) !== 0 ? dy : -dy;
        } else if ((flag & 32) === 0) {
          y += view.getInt16(cursor);
          cursor += 2;
        }
        ys[i] = y;
      }

      const contours: GlyphPoint[][] = [];
      let startIdx = 0;
      for (let c = 0; c < numContours; c++) {
        const endIdx = endPts[c]!;
        const pts: GlyphPoint[] = [];
        for (let i = startIdx; i <= endIdx; i++) {
          pts.push({
            x: xs[i]!,
            y: ys[i]!,
            onCurve: (flags[i]! & 1) !== 0
          });
        }
        contours.push(pts);
        startIdx = endIdx + 1;
      }

      const decoded: RawGlyphData = {
        advanceWidth: adv,
        lsb,
        xMin,
        yMin,
        xMax,
        yMax,
        contours
      };
      resolvedGlyphs[gid] = decoded;
      return decoded;
    } else {
      const contours: GlyphPoint[][] = [];
      let cursor = pos + 10;
      while (true) {
        const compFlags = view.getUint16(cursor);
        const compGid = view.getUint16(cursor + 2);
        cursor += 4;
        let dx = 0;
        let dy = 0;
        if ((compFlags & 1) !== 0) {
          dx = view.getInt16(cursor);
          dy = view.getInt16(cursor + 2);
          cursor += 4;
        } else {
          dx = view.getInt8(cursor);
          dy = view.getInt8(cursor + 1);
          cursor += 2;
        }
        let a = 1;
        let b = 0;
        let c = 0;
        let d = 1;
        if ((compFlags & 8) !== 0) {
          a = d = view.getInt16(cursor) / 16384;
          cursor += 2;
        } else if ((compFlags & 64) !== 0) {
          a = view.getInt16(cursor) / 16384;
          d = view.getInt16(cursor + 2) / 16384;
          cursor += 4;
        } else if ((compFlags & 128) !== 0) {
          a = view.getInt16(cursor) / 16384;
          b = view.getInt16(cursor + 2) / 16384;
          c = view.getInt16(cursor + 4) / 16384;
          d = view.getInt16(cursor + 6) / 16384;
          cursor += 8;
        }
        const subGlyph = decodeGlyph(compGid);
        for (const contour of subGlyph.contours) {
          contours.push(
            contour.map((pt) => ({
              x: Math.round(pt.x * a + pt.y * c + dx),
              y: Math.round(pt.x * b + pt.y * d + dy),
              onCurve: pt.onCurve
            }))
          );
        }
        if ((compFlags & 32) === 0) break;
      }

      const decoded: RawGlyphData = {
        advanceWidth: adv,
        lsb,
        xMin,
        yMin,
        xMax,
        yMax,
        contours
      };
      resolvedGlyphs[gid] = decoded;
      return decoded;
    }
  }

  for (let gid = 0; gid < numGlyphs; gid++) {
    decodeGlyph(gid);
  }

  const parsed: ParsedSfnt = {
    unitsPerEm,
    ascender,
    descender,
    numGlyphs,
    cmap,
    rawGlyphs: resolvedGlyphs as RawGlyphData[]
  };
  cachedFonts.set(variant, parsed);
  return parsed;
}

export function getEmbeddedFont(): EmbeddedFont {
  return parseSfnt("ui-regular");
}

function isWideUnicode(codePoint: number): boolean {
  return (
    (codePoint >= 0x1100 && codePoint <= 0x11ff) ||
    (codePoint >= 0x2e80 && codePoint <= 0x9fff) ||
    (codePoint >= 0xac00 && codePoint <= 0xd7af) ||
    (codePoint >= 0xf900 && codePoint <= 0xfaff) ||
    (codePoint >= 0x1f300 && codePoint <= 0x1faff)
  );
}

function makeRectContour(x1: number, y1: number, x2: number, y2: number): readonly GlyphPoint[] {
  return [
    { x: x1, y: y1, onCurve: true },
    { x: x1, y: y2, onCurve: true },
    { x: x2, y: y2, onCurve: true },
    { x: x2, y: y1, onCurve: true }
  ];
}

function makeStroke(x1: number, y1: number, x2: number, y2: number, thickness = 56): readonly GlyphPoint[] {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.max(1, Math.hypot(dx, dy));
  const nx = (-dy / len) * (thickness / 2);
  const ny = (dx / len) * (thickness / 2);
  return [
    { x: Math.round(x1 + nx), y: Math.round(y1 + ny), onCurve: true },
    { x: Math.round(x2 + nx), y: Math.round(y2 + ny), onCurve: true },
    { x: Math.round(x2 - nx), y: Math.round(y2 - ny), onCurve: true },
    { x: Math.round(x1 - nx), y: Math.round(y1 - ny), onCurve: true }
  ];
}

function synthesizeIdeographOutline(codePoint: number): GlyphOutline {
  const strokes: (readonly GlyphPoint[])[] = [];
  const arch = codePoint % 4;
  if (arch === 0) {
    strokes.push(makeStroke(490, 710, 490, 610, 56));
    strokes.push(makeStroke(160, 610, 840, 610, 54));
    strokes.push(makeStroke(160, 610, 160, 490, 52));
    strokes.push(makeStroke(840, 610, 840, 490, 52));
    strokes.push(makeStroke(240, 460, 760, 460, 52));
    strokes.push(makeStroke(140, 310, 860, 310, 56));
    strokes.push(makeStroke(500, 730, 500, 80, 60));
    strokes.push(makeStroke(460, 320, 140, 100, 54));
    strokes.push(makeStroke(540, 320, 860, 100, 54));
  } else if (arch === 1) {
    strokes.push(makeStroke(490, 710, 490, 600, 58));
    strokes.push(makeStroke(140, 600, 860, 600, 56));
    strokes.push(makeStroke(220, 430, 780, 430, 54));
    strokes.push(makeStroke(140, 270, 860, 270, 56));
    strokes.push(makeStroke(380, 430, 200, 80, 56));
    strokes.push(makeStroke(620, 430, 820, 80, 56));
  } else if (arch === 2) {
    strokes.push(makeStroke(150, 680, 150, 80, 56));
    strokes.push(makeStroke(150, 680, 420, 680, 54));
    strokes.push(makeStroke(150, 480, 420, 480, 50));
    strokes.push(makeStroke(850, 680, 850, 80, 56));
    strokes.push(makeStroke(580, 680, 850, 680, 54));
    strokes.push(makeStroke(580, 480, 850, 480, 50));
    strokes.push(makeStroke(280, 310, 720, 310, 52));
    strokes.push(makeStroke(380, 380, 340, 100, 52));
    strokes.push(makeStroke(620, 380, 620, 100, 52));
  } else {
    strokes.push(makeStroke(160, 650, 840, 650, 58));
    strokes.push(makeStroke(820, 650, 540, 420, 56));
    strokes.push(makeStroke(520, 440, 520, 80, 60));
    strokes.push(makeStroke(520, 80, 380, 160, 54));
    strokes.push(makeStroke(180, 340, 820, 340, 54));
  }

  return {
    codePoint,
    advanceWidth: 980,
    leftSideBearing: 110,
    xMin: 110,
    yMin: 60,
    xMax: 890,
    yMax: 720,
    contours: strokes
  };
}

export function getGlyphOutline(
  codePoint: number,
  fontFamily: "ui" | "mono" = "ui",
  fontWeight: 400 | 500 | 600 | 700 = 500
): GlyphOutline {
  const cacheKey = `${codePoint}:${fontFamily}:${fontWeight}`;
  const hit = outlineCache.get(cacheKey);
  if (hit) return hit;

  const variant: FontVariant =
    fontFamily === "mono"
      ? "mono"
      : fontWeight >= 600
        ? "ui-bold"
        : "ui-regular";

  let font = parseSfnt(variant);
  let gid = font.cmap.get(codePoint);
  if (gid === undefined && variant !== "mono") {
    const monoFont = parseSfnt("mono");
    const monoGid = monoFont.cmap.get(codePoint);
    if (monoGid !== undefined) {
      font = monoFont;
      gid = monoGid;
    }
  }

  if (gid === undefined) {
    if (isWideUnicode(codePoint)) {
      const cjk = synthesizeIdeographOutline(codePoint);
      outlineCache.set(cacheKey, cjk);
      return cjk;
    }
    const fallback = getGlyphOutline(0x3f, fontFamily, fontWeight);
    outlineCache.set(cacheKey, fallback);
    return fallback;
  }

  const raw = font.rawGlyphs[gid]!;
  // Comfortable letter-spacing tracking so characters have clear breathing room
  const tracking =
    fontFamily === "mono"
      ? 35
      : fontWeight >= 600
        ? 46
        : 40;
  const shiftX = Math.round(tracking / 2);

  if (raw.contours.length === 0) {
    const spaceOut: GlyphOutline = {
      codePoint,
      advanceWidth: raw.advanceWidth + tracking,
      leftSideBearing: 0,
      xMin: 0,
      yMin: 0,
      xMax: 0,
      yMax: 0,
      contours: []
    };
    outlineCache.set(cacheKey, spaceOut);
    return spaceOut;
  }

  const shiftedContours = raw.contours.map((contour) =>
    contour.map((pt) => ({
      x: pt.x + shiftX,
      y: pt.y,
      onCurve: pt.onCurve
    }))
  );

  const out: GlyphOutline = {
    codePoint,
    advanceWidth: raw.advanceWidth + tracking,
    leftSideBearing: raw.lsb + shiftX,
    xMin: raw.xMin + shiftX,
    yMin: raw.yMin,
    xMax: raw.xMax + shiftX,
    yMax: raw.yMax,
    contours: shiftedContours
  };
  outlineCache.set(cacheKey, out);
  return out;
}
